// the cash amounts a discounted price can come from (the tier follows the cash amount)
function loCashCands(v) {
  const c = [];
  if (v < 1000) c.push(v);
  if (v / 0.96 >= 1000 && v / 0.96 < 3000) c.push(v / 0.96);
  if (v / 0.92 >= 3000 && v / 0.92 < 10000) c.push(v / 0.92);
  if (v / 0.86 >= 10000) c.push(v / 0.86);
  return c.length ? c : [v];
}
// a stored curve back in cash; where two readings are possible (e.g. 989.60 = cash 989.60, or 1,030.85 less 4%),
// the one that fits the neighbouring quantities wins
const LO_CASH_MEMO = new Map();
function loCashRow(row) {
  if (LO_CASH_MEMO.has(row)) return LO_CASH_MEMO.get(row);
  const ks = Object.keys(row).map(Number).sort((a, b) => a - b), cand = ks.map(k => loCashCands(row[k])), out = {};
  ks.forEach((k, i) => { if (cand[i].length === 1) out[k] = cand[i][0]; });
  const fixedIdx = ks.map((k, i) => out[k] != null ? i : -1).filter(i => i >= 0);
  ks.forEach((k, i) => {
    if (out[k] != null) return;
    const L = fixedIdx.filter(j => j < i), Rr = fixedIdx.filter(j => j > i);
    const at = (a, b) => out[ks[a]] + (out[ks[b]] - out[ks[a]]) * (k - ks[a]) / (ks[b] - ks[a]);
    const l = L[L.length - 1], r = Rr[0];
    // the fixed neighbours bound it (prices rise with quantity); otherwise follow their line, extrapolating at the ends
    const lo = l != null ? out[ks[l]] : -Infinity, hi = r != null ? out[ks[r]] : Infinity;
    const inside = cand[i].filter(c => c >= lo && c <= hi);
    const guess = l != null && r != null ? at(l, r) : L.length > 1 ? at(L[L.length - 2], l) : Rr.length > 1 ? at(r, Rr[1]) : l != null ? out[ks[l]] : r != null ? out[ks[r]] : cand[i][0];
    // both readings occur on Excard's lists; the one nearest the neighbours' line (within their bounds) is right ~95% of the time
    const pool = inside.length ? inside : cand[i];
    out[k] = pool.reduce((b, c) => Math.abs(c - guess) < Math.abs(b - guess) ? c : b);
  });
  ks.forEach(k => { out[k] = Math.round(out[k] * 20) / 20; });       // Excard prices are whole 5-sen steps
  // lists that start at 250 / 300: Excard prices 500 as 300
  if (ks[0] >= 250 && out[300] != null && out[500] != null) out[500] = out[300];
  LO_CASH_MEMO.set(row, out);
  return out;
}
function loAt(row, q, cash) {
  if (!cash) row = loCashRow(row);
  const ks = Object.keys(row).map(Number).sort((a, b) => a - b); if (!ks.length) return null;
  const val = k => row[k];
  if (row[q] != null) return val(q);
  if (q <= ks[0]) return val(ks[0]) * q / ks[0];
  for (let i = 1; i < ks.length; i++) if (q <= ks[i]) { const a = ks[i - 1], b = ks[i]; return val(a) + (val(b) - val(a)) * (q - a) / (b - a); }
  const a = ks[ks.length - 2], b = ks[ks.length - 1]; return val(b) + (val(b) - val(a)) * (q - b) / (b - a);
}
const LO_CURVE_LAM = { 'Matt Lamination (Front)': 'Matte Lamination (Front)', 'Matt Lamination (Both)': 'Matte Lamination (Both)', 'Gloss Water Base Varnish (Front)': 'Gloss Waterbase Varnish (Front)' };
function loSheet(cfg, lam, q) {
  const key = [cfg.size, cfg.paper, lam, cfg.colour].join('|');
  if (LO_PL[key]) return loAt(LO_PL[key], q, true);
  const E = typeof window !== 'undefined' && window.PricingEngine, cv = E && E.DATA.params.loosesheet_plx && E.DATA.params.loosesheet_plx.curves;
  const row = cv && cv[[cfg.size, cfg.paper, LO_CURVE_LAM[lam] || lam, cfg.colour].join('|')];
  // the Gloss Art 80gsm curves were captured as plain cash
  return row ? loAt(row, q, /Gloss Art Paper 80gsm/.test(cfg.paper || '')) : null;
}
// add-ons sampled live (A4 / A3 Gloss Art 128gsm; hole punching, perforation checked size-independent)
const LO_ADD = {
  punch: [[0, 0], [1000, 7.30], [5000, 31.50], [20000, 134.15]],
  rc: [[0, 0], [500, 12.10], [1000, 30.35], [5000, 140.65], [20000, 607.05]],
  perfLine: [[0, 0], [1000, 26.68], [5000, 123.70], [20000, 534.65]],   // per line, plus RM7.30
};
// hot stamping, one colour (A3 Gloss Art 128gsm): by block area at 500 / 1,000 / 5,000 / 20,000
const LO_HS_S = [[500, 47.30], [1000, 67.90], [5000, 260.75], [20000, 1078.55]];   // 90 × 30 mm block
const LO_HS_B = [[500, 348.05], [1000, 704.60], [5000, 3079.15]];                  // 206 × 294 mm block
function loHsOne(size, q) {
  const m = String(size || '').match(/(\d+)mm x (\d+)mm/); if (!m) return 0;
  const a = +m[1] * +m[2], s = dlsLin(LO_HS_S, q), b = dlsLin(LO_HS_B, q);
  const mid = 224.35 * (s / 67.90 + b / 704.60) / 2;                                // 101 × 144 mm = RM224.35 at 1,000
  if (a <= 2700) return s;
  if (a <= 14544) return s + (mid - s) * (a - 2700) / (14544 - 2700);
  return mid + (b - mid) * (a - 14544) / (60564 - 14544);
}
function loHotStampCost(cfg, q) {
  if (!loVis(cfg).hs) return 0;
  const m = String(cfg.hot_stamping || '').match(/^(\d)C \((Front|Back)\)$/); if (!m) return 0;
  const side = m[2].toLowerCase(); let t = 0;
  for (let i = 1; i <= +m[1]; i++) t += loHsOne(cfg['hs_size_' + side + '_' + i], q);
  return Math.round(t * 100) / 100;
}
function loPriceBase(cfg, q) {
  if (!LO_SZ[cfg.size] || !cfg.paper || !cfg.colour) return null;
  const lam = loVis(cfg).lam ? (cfg.lam || 'Not Required') : 'Not Required';
  let base;
  const sv = !LO_PL[[cfg.size, cfg.paper, lam, cfg.colour].join('|')] && LO_SUV[lam];
  if (sv) {   // Spot UV / water-base finishes priced off their parent lamination
    const parent = loSheet(cfg, sv.parent, q); if (parent == null) return null;
    base = parent * dlsLin(sv.ratio[loSz(cfg)] || sv.ratio.def, q);
  } else base = loSheet(cfg, lam, q);
  if (base == null) return null;
  const v = loVis(cfg);
  let add = 0;
  if (v.creased && cfg.creasing === 'Crease + Fold') add += 0.08 * q;
  if (v.hp && cfg.hole_punch && cfg.hole_punch !== 'Not Required') add += dlsLin(LO_ADD.punch, q);
  if (v.rc && cfg.rcorner && cfg.rcorner !== 'Not Required') add += dlsLin(LO_ADD.rc, q);
  if (v.perfOn) { const n = +(String(cfg.perforation).match(/(\d)/) || [])[1] || 1; add += 7.30 + n * dlsLin(LO_ADD.perfLine, q); }
  if (DLS_ENV[cfg.envelope]) add += DLS_ENV[cfg.envelope] * 0.978 * q;
  const N = BC_PKG_N[cfg.package] || 1;
  return Math.round((base + add) * N * 100) / 100;
}

